import map from "./cdn-assets-map.json";

/**
 * Public origin of the Vercel Blob store that serves the standardized media.
 * Generated by `npm run upload:cdn` — do not edit by hand.
 */
export const CDN_BASE_URL: string = map.baseUrl;

/** Standardized asset filename → public CDN URL. */
export const CDN_ASSETS: Record<string, string> = map.assets;

/**
 * Resolves a standardized media filename (e.g. "MISU__hero-cover.mp4") to its
 * public CDN URL. Throws during development if the name is not in the map, so a
 * typo fails fast instead of silently rendering a broken image.
 */
export function cdnAsset(name: keyof typeof CDN_ASSETS): string {
  const url = CDN_ASSETS[name];
  if (!url) {
    throw new Error(
      `Unknown CDN asset "${String(name)}". Run \`npm run upload:cdn\` to refresh src/config/cdn-assets-map.json.`,
    );
  }
  return url;
}
